      "No contexto profissional, ética aplicada (ou ética profissional) trata dos princípios de conduta específicos de uma categoria ou atividade — no caso da atividade policial, envolve honestidade, imparcialidade, respeito aos direitos humanos, e o compromisso com a proteção da sociedade acima de interesses pessoais. Diferente da lei (que pode ser cumprida por medo de punição), a ética pressupõe uma adesão interna, convicta, aos valores que orientam a conduta correta.",
      "Um conceito central é o de conduta profissional: o comportamento esperado de quem exerce uma função pública, indo além do que a lei formalmente exige — mesmo quando uma conduta não seria juridicamente punível, ela pode ser eticamente reprovável se contrariar os princípios de honestidade, urbanidade, zelo e comprometimento com o interesse coletivo esperados de um agente público."
