    "title": "Ética no serviço público: princípios gerais",
    "assunto": "Ética funcional",
    "tecnica": "Conexão dos princípios éticos com os princípios constitucionais já estudados (LIMPE)",
    "competencia": "Reconhecer os princípios éticos gerais que orientam a conduta do servidor público",
    "dificuldade": "Fácil",
    "tempoLeituraMin": 6,
    "tempoExercicioMin": 5,
    "bancaRatings": {
      "FGV": 3,
      "CESPE": 4,
      "FCC": 4,
      "ENEM": 3
    },
    "termosChave": [
      "urbanidade",
      "zelo",
      "moralidade administrativa"
    ],
    "corpo": [
      "A ética no serviço público se conecta diretamente aos princípios constitucionais da Administração já estudados (LIMPE: legalidade, impessoalidade, moralidade, publicidade, eficiência) — mas vai além deles, incorporando valores de conduta pessoal que nem sempre estão explicitamente positivados em lei, como honestidade, urbanidade (tratamento cortês e respeitoso a colegas e cidadãos), assiduidade, pontualidade e zelo pelo patrimônio público.",
      "O Decreto 1.171/1994, que instituiu o Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal, é referência frequentemente citada em prova, mesmo quando o cargo em disputa não é federal — ele estabelece que a dignidade, o decoro, o zelo, a eficácia e a consciência dos princípios morais são primados maiores que devem nortear o servidor público, e que o trabalho desenvolvido pelo servidor deve ser entendido como acréscimo ao seu próprio bem-estar, já que ele passa a maior parte de sua vida no local de trabalho.",
      "Moralidade administrativa, no sentido ético (para além do sentido jurídico já visto em Direito Administrativo), exige que o servidor distinga não apenas entre o legal e o ilegal, mas entre o honesto e o desonesto — um ato pode passar no teste da estrita legalidade formal e ainda assim ser eticamente reprovável, se voltado a interesses pessoais disfarçados de interesse público."
    ],
    "pontosChave": [
      "Ética funcional vai além do LIMPE constitucional, incorporando honestidade, urbanidade, zelo, assiduidade e pontualidade.",
      "Decreto 1.171/1994 (Código de Ética do Servidor Público Federal) é referência frequentemente cobrada, mesmo fora do âmbito federal.",
      "Moralidade administrativa (sentido ético) distingue honesto de desonesto, além de distinguir legal de ilegal."
    ],
    "checkRapido": {
      "pergunta": "Segundo a lógica do Código de Ética Profissional do Servidor Público (Decreto 1.171/1994), o trabalho do servidor deve ser entendido como:",
      "opcoes": [
        "Um fardo a ser cumprido com o mínimo esforço possível",
        "Um acréscimo ao seu próprio bem-estar, já que passa a maior parte de sua vida no ambiente de trabalho",
        "Uma atividade totalmente dissociada de sua vida pessoal"
      ],
      "correta": 1,
      "justificativa": "O Código estabelece expressamente essa visão: como o servidor passa boa parte de sua existência no trabalho, ele deve ser entendido como parte importante de seu próprio bem-estar, reforçando a ideia de que a dedicação ao serviço público não é um mero cumprimento burocrático, mas parte da realização pessoal do servidor."
    },
    "oQueCobra": "Reconhecer os princípios éticos gerais do serviço público, especialmente os previstos no Decreto 1.171/1994.",
    "precisaSaberAntes": "Relembrar os princípios constitucionais LIMPE (art. 37 da CF), já vistos em Direito Constitucional e Administrativo.",
    "explicacao": [
      {
        "titulo": "Vedações éticas do Decreto 1.171/1994",
        "texto": "O Código veda expressamente condutas como: usar o cargo para obter vantagem pessoal, prejudicar deliberadamente a reputação de outros servidores, receber propina ou presentes de quem tenha interesse direto na decisão do servidor, e retardar qualquer prestação de contas de sua responsabilidade — condutas que, mesmo sem tipificação penal específica em alguns casos, configuram falta ética grave."
      },
      {
        "titulo": "Comissões de Ética",
        "texto": "Órgãos públicos, seguindo o modelo do Decreto 1.171/1994, costumam manter Comissões de Ética responsáveis por orientar e aconselhar sobre a interpretação e aplicação do código, além de apurar eventuais faltas éticas — funcionam de forma complementar às Corregedorias (foco disciplinar) e ao controle externo (Ministério Público)."
      }
    ],
    "comoIdentificar": "Questões que citam o Decreto 1.171/1994 diretamente, ou que descrevem uma conduta e pedem para avaliar sua adequação ética.",
    "pegadinhas": [
      "Achar que princípios éticos são apenas repetição do LIMPE constitucional, sem valores adicionais próprios.",
      "Não reconhecer o Decreto 1.171/1994 como referência frequentemente cobrada mesmo fora da esfera federal.",
      "Confundir Comissão de Ética (orientação e aconselhamento) com Corregedoria (apuração disciplinar) — são complementares, não idênticas."
    ],
    "resumoFrase": "Ética funcional vai além do LIMPE — o Decreto 1.171/1994 é referência central, mesmo em provas estaduais/municipais.",
    "proximoTitulo": "Ética militar: hierarquia, disciplina e valores institucionais",
