    "explicacaoComoSeTivesse12": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Ética no serviço público: princípios gerais\", a ideia principal é: A ética no serviço público se conecta diretamente aos princípios constitucionais da Administração já estudados (LIMPE: legalidade, impessoalidade, moralidade, publicidade, eficiência) — mas vai além deles, incorporando valores de conduta pessoal que nem sempre. Para estudar sem travar, guarde primeiro estas palavras-chave: urbanidade, zelo, moralidade administrativa. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Ética funcional vai além do LIMPE — o Decreto 1.171/1994 é referência central, mesmo em provas estaduais/municipais.",
