    "corpo": [
      "Hierarquia e disciplina são os pilares estruturantes das organizações militares, incluindo as Polícias Militares — a Constituição os reconhece expressamente como base institucional (art. 42, aplicável às polícias militares por força do art. 42, §1º). Hierarquia é a ordenação de autoridade em níveis diferentes de escalões, conforme postos e graduações, com respeito e subordinação do menor grau ao maior. Disciplina é a rigorosa observância e o acatamento integral das leis, regulamentos, normas e disposições que fundamentam o organismo militar, e coordenam seu funcionamento harmônico.",
      "Eticamente, a hierarquia não deve ser confundida com humilhação ou tratamento indigno do subordinado — o exercício da autoridade hierárquica deve ser pautado por urbanidade e respeito à dignidade da pessoa, mesmo diante da relação de subordinação. O abuso de autoridade dentro da própria cadeia hierárquica (tratamento humilhante, ordens manifestamente ilegais) é falta ética grave, além de poder configurar infração penal ou disciplinar específica.",
      "Valores institucionais recorrentes na cultura das corporações militares incluem: patriotismo, civismo, coragem, lealdade, camaradagem (espírito de corpo, solidariedade entre os integrantes da corporação) e espírito de sacrifício (disposição para colocar o interesse coletivo/institucional acima do interesse pessoal, quando necessário para a missão). Esses valores, embora nem sempre positivados em lei com a mesma precisão de um código, orientam a formação e a avaliação de conduta dos militares em toda a carreira."
    ],
