    "title": "Conflito de interesses e nepotismo",
    "assunto": "Conflito de interesses",
    "tecnica": "Identificação da sobreposição entre interesse pessoal e interesse público na decisão",
    "competencia": "Reconhecer situações de conflito de interesses e a vedação ao nepotismo",
    "dificuldade": "Média",
    "tempoLeituraMin": 6,
    "tempoExercicioMin": 5,
    "bancaRatings": {
      "FGV": 3,
      "CESPE": 4,
      "FCC": 4,
      "ENEM": 2
    },
    "termosChave": [
      "conflito de interesses",
      "nepotismo",
      "Súmula Vinculante 13"
    ],
    "corpo": [
      "Conflito de interesses ocorre quando o interesse particular do agente público (ou de pessoas a ele ligadas) pode influenciar, de forma real ou aparente, o exercício imparcial e objetivo de sua função — não é preciso que haja efetivamente um prejuízo concreto ao interesse público para configurar o conflito; basta a possibilidade de que o interesse pessoal comprometa (ou pareça comprometer) a isenção da decisão.",
      "Nepotismo é uma das formas mais conhecidas de conflito de interesses: a nomeação de parentes (cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade, até o terceiro grau) para cargos públicos de confiança, sem concurso, especialmente quando há relação de subordinação direta ou indireta entre o nomeante e o nomeado. O Supremo Tribunal Federal consolidou o entendimento na Súmula Vinculante 13, vedando o nepotismo em toda a Administração Pública, direta e indireta, em qualquer dos Poderes, independentemente de lei específica que o proíba expressamente.",
      "O chamado 'nepotismo cruzado' é uma forma de burlar a vedação: em vez de nomear diretamente seu próprio parente, o agente nomeia parente de um colega, que por sua vez nomeia parente do primeiro — a jurisprudência reconhece essa prática como igualmente vedada, por configurar em essência a mesma quebra de imparcialidade que o nepotismo direto busca coibir."
    ],
    "pontosChave": [
      "Conflito de interesses: interesse particular pode influenciar (real ou aparentemente) o exercício imparcial da função pública.",
      "Nepotismo: nomeação de parente (até 3º grau) para cargo de confiança, vedado pela Súmula Vinculante 13 do STF.",
      "Nepotismo cruzado (troca de favores entre agentes para nomear parentes um do outro) também é vedado pela jurisprudência."
    ],
    "checkRapido": {
      "pergunta": "Um agente público nomeia o filho de um colega para um cargo de confiança, e esse colega, em contrapartida, nomeia o filho do primeiro agente para outro cargo de confiança. Essa prática é conhecida como:",
      "opcoes": [
        "Nepotismo direto",
        "Nepotismo cruzado",
        "Conduta permitida, pois não há parentesco direto na nomeação"
      ],
      "correta": 1,
      "justificativa": "Essa troca de favores para burlar a vedação direta ao nepotismo é conhecida como nepotismo cruzado — a jurisprudência do STF reconhece essa prática como igualmente vedada, por representar, na essência, a mesma quebra de imparcialidade que a Súmula Vinculante 13 busca coibir."
    },
    "oQueCobra": "Reconhecer situações de conflito de interesses, especialmente nepotismo direto e cruzado, e sua vedação jurisprudencial.",
    "precisaSaberAntes": "Relembrar os princípios de impessoalidade e moralidade (LIMPE), já vistos em Direito Constitucional e Administrativo.",
    "explicacao": [
      {
        "titulo": "Exceções reconhecidas pela jurisprudência",
        "texto": "A vedação ao nepotismo não se aplica, em regra, a cargos de natureza técnica ou científica, desde que comprovada a qualificação profissional específica exigida e ausente qualquer favorecimento pessoal na escolha — mas essa exceção é interpretada de forma restritiva pela jurisprudência, exigindo real comprovação de mérito técnico."
      },
      {
        "titulo": "Conflito de interesses além do nepotismo",
        "texto": "Outras situações de conflito de interesses incluem: participar de decisão que beneficie empresa em que o agente ou familiar próximo tenha participação societária, ou aceitar presentes/vantagens de quem tenha interesse em decisão sob sua responsabilidade — o critério central é sempre a possibilidade de comprometimento da imparcialidade, não apenas o parentesco."
      }
    ],
    "comoIdentificar": "Questões que descrevem uma nomeação envolvendo parentesco, direto ou cruzado, ou uma situação de decisão com potencial benefício pessoal ao agente.",
    "pegadinhas": [
      "Achar que nepotismo cruzado (sem parentesco direto na nomeação) é conduta permitida — é igualmente vedado pela jurisprudência.",
      "Não reconhecer que conflito de interesses não exige prejuízo efetivo comprovado, bastando a possibilidade de comprometimento da imparcialidade.",
      "Aplicar a exceção de cargo técnico/científico sem a devida comprovação de qualificação profissional específica."
    ],
    "resumoFrase": "Nepotismo cruzado é vedado como o direto — e conflito de interesses não exige prejuízo comprovado, só a possibilidade de comprometer a imparcialidade.",
