    "explicacaoComoSeTivesse12": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Conflito de interesses e nepotismo\", a ideia principal é: Conflito de interesses ocorre quando o interesse particular do agente público (ou de pessoas a ele ligadas) pode influenciar, de forma real ou aparente, o exercício imparcial e objetivo de sua função — não é preciso que haja efetivamente um prejuízo concreto. Para estudar sem travar, guarde primeiro estas palavras-chave: conflito de interesses, nepotismo, Súmula Vinculante 13. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Nepotismo cruzado é vedado como o direto — e conflito de interesses não exige prejuízo comprovado, só a possibilidade de comprometer a imparcialidade.",
