    "corpo": [
      "Corrupção, no sentido amplo, é o abuso de posição de poder ou confiança para obter benefício pessoal ilegítimo — engloba desde grandes esquemas de desvio de recursos públicos até pequenas transgressões cotidianas ('pequena corrupção' ou 'jeitinho'), como aceitar uma pequena vantagem para agilizar um atendimento ou 'fechar os olhos' para uma infração menor. Eticamente, a gravidade não está apenas no valor envolvido, mas na quebra de confiança que qualquer forma de corrupção representa entre o agente público e a sociedade que ele serve.",
      "Corrupção passiva (art. 317 do Código Penal, já estudado) é solicitar ou receber vantagem indevida, ou aceitar promessa dela, em razão da função — o agente público é quem recebe. Corrupção ativa (art. 333) é oferecer ou prometer vantagem indevida a funcionário público para determiná-lo a praticar, omitir ou retardar ato de ofício — o particular é quem oferece. Ambas configuram crime, mesmo que a vantagem não seja efetivamente entregue ou aceita (basta a solicitação, oferta ou promessa).",
      "A improbidade administrativa (já estudada em Direito Administrativo) é a consequência jurídico-civil mais associada à corrupção institucionalizada, mas o combate à corrupção também depende fortemente de uma cultura ética consolidada dentro das instituições — treinamento continuado, canais de denúncia protegidos (proteção ao denunciante, ou whistleblower), e lideranças que modelem o comportamento íntegro esperado são tão importantes quanto a repressão penal e civil para a prevenção efetiva da corrupção no dia a dia da atividade policial."
    ],
    "pontosChave": [
      "Corrupção passiva: agente público solicita/recebe vantagem indevida. Corrupção ativa: particular oferece/promete vantagem ao agente.",
      "'Pequena corrupção' (jeitinho, pequena vantagem) é eticamente grave pela quebra de confiança, não só pelo valor envolvido.",
      "Prevenção efetiva da corrupção depende de cultura ética institucional, além da repressão penal/civil (improbidade)."
    ],
