    "corpo": [
      "Assédio moral é a exposição do trabalhador a situações humilhantes e constrangedoras, repetitivas e prolongadas no tempo, durante o exercício de suas funções — geralmente praticado por superior hierárquico em relação a subordinado (assédio vertical descendente), embora também possa ocorrer entre colegas do mesmo nível (assédio horizontal) ou, mais raramente, de subordinado contra superior. Diferente de uma cobrança profissional legítima (ainda que firme), o assédio moral tem caráter sistemático, deliberadamente humilhante, e sem finalidade profissional legítima que o justifique.",
      "Assédio sexual, tipificado como crime no Código Penal (art. 216-A), é constranger alguém com o intuito de obter vantagem ou favorecimento sexual, prevalecendo-se o agente de sua condição de superior hierárquico ou ascendência inerentes ao exercício de emprego, cargo ou função — a relação de subordinação (ainda que não necessariamente hierárquica formal, podendo ser de ascendência funcional) é elemento central do tipo penal, diferenciando-o de outras condutas de importunação sexual sem essa relação específica.",
      "Em ambas as modalidades de assédio, um ponto central para diferenciar de conflito profissional legítimo é a ausência de finalidade relacionada ao trabalho: uma cobrança dura, porém justificada por falha real de desempenho, tende a ser conduta profissional aceitável (ainda que desagradável); humilhação recorrente, comentários de conotação sexual insistentes, ou pressão para obter favorecimento sexual, sem qualquer relação com o desempenho profissional, configuram assédio."
    ],
    "pontosChave": [
      "Assédio moral: humilhação sistemática e prolongada, sem finalidade profissional legítima — pode ser vertical ou horizontal.",
      "Assédio sexual (art. 216-A CP): constranger para obter favorecimento sexual, prevalecendo-se de superioridade hierárquica/ascendência funcional.",
      "Diferença chave: cobrança profissional legítima tem finalidade relacionada ao trabalho; assédio não tem, ou usa o trabalho como pretexto."
    ],
