        "respostaEsperada": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Assédio moral e sexual no ambiente de trabalho\", a ideia principal é: Assédio moral é a exposição do trabalhador a situações humilhantes e constrangedoras, repetitivas e prolongadas no tempo, durante o exercício de suas funções — geralmente praticado por superior hierárquico em relação a subordinado (assédio vertical. Para estudar sem travar, guarde primeiro estas palavras-chave: assédio moral, assédio sexual, relação de subordinação. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Assédio moral é humilhação sistemática sem finalidade profissional real; assédio sexual não exige contato físico — ambos exigem análise de padrão e finalidade, não fato isolado.",
