    "corpo": [
      "O uso de redes sociais por agentes públicos, especialmente militares, levanta questões éticas específicas: mesmo em perfil pessoal, publicações podem ser associadas à imagem institucional da corporação, especialmente quando o agente se identifica publicamente com sua função (uso de farda em foto de perfil, menção ao cargo/local de trabalho). Isso não significa que o agente perca completamente sua liberdade de expressão pessoal, mas exige maior cautela do que a de um cidadão comum, dado o vínculo com a função pública exercida.",
      "Compartilhar informações sigilosas de investigações, fotos de ocorrências com identificação de vítimas ou suspeitos, ou opiniões discriminatórias/preconceituosas em redes sociais são condutas que extrapolam a liberdade de expressão pessoal e configuram falta ética grave — violando, respectivamente, o sigilo funcional, a proteção à imagem de terceiros, e os princípios de igualdade e não discriminação já estudados em Direitos Humanos.",
      "Um critério prático frequentemente usado para avaliar a adequação ética de uma publicação é perguntar: essa postagem, se tornada pública e associada à instituição, comprometeria a confiança da sociedade na corporação ou na atuação imparcial do agente? Publicações que expõem viés discriminatório, revelam informações sigilosas, ou depreciam a instituição/colegas costumam falhar nesse teste."
    ],
