    "corpo": [
      "Este capítulo final integra os conceitos éticos estudados ao longo do módulo com o conteúdo de uso progressivo da força, já visto em Direitos Humanos — a decisão de escalar (ou não) o nível de força em uma abordagem não é apenas uma questão técnica ou tática, é fundamentalmente uma decisão ética, tomada em frações de segundo, que reflete os valores internalizados pelo agente ao longo de sua formação.",
      "Responsabilidade ética individual significa que, mesmo em contexto de hierarquia e disciplina, cada agente mantém um juízo de discernimento pessoal sobre a legitimidade de suas próprias ações — a obediência devida a superiores não elimina a responsabilidade ética (e, como já visto, também jurídica) do próprio agente por atos manifestamente abusivos, ainda que ordenados. Ética profissional consolidada não é a ausência de erros, mas a capacidade de reconhecer, reportar e corrigir condutas equivocadas quando identificadas — inclusive as próprias.",
      "Accountability (prestação de contas) é o conceito que fecha esse ciclo: agentes públicos, especialmente os que exercem poder de uso da força, devem estar sujeitos a mecanismos efetivos de responsabilização (interna, pelo controle disciplinar e ético; externa, pelo Ministério Público e sociedade civil) — a existência de accountability robusta não enfraquece a atividade policial legítima; ao contrário, fortalece a confiança pública necessária para que essa atividade seja exercida com legitimidade social."
    ],
